  ('ki-a-clothing-q1', 'question_to_client', 'creator', 'business', 'Что сейчас происходит в бренде: запуск, новая коллекция, обновление страницы или регулярная работа', 'Что сейчас происходит в бренде: запуск, новая коллекция, обновление страницы или регулярная работа?', NULL, NULL, NULL, NULL, 'any', 'business', 'required', 'normal', 'notion', 'https://app.notion.com/p/3aba54abb3e281d18091f4bfa67ef8e3?pvs=204', 'Бренды одежды и текстиля', 'approved', 1, 'priority-a-clothing-question-1'),
  ('ki-a-clothing-q2', 'question_to_client', 'creator', 'context', 'Почему решили заняться контентом именно сейчас', 'Почему решили заняться контентом именно сейчас?', NULL, NULL, NULL, NULL, 'any', 'business', 'recommended', 'normal', 'notion', 'https://app.notion.com/p/3aba54abb3e281d18091f4bfa67ef8e3?pvs=204', 'Бренды одежды и текстиля', 'approved', 1, 'priority-a-clothing-question-2'),
  ('ki-a-clothing-ob1', 'objection_response', 'creator', 'objections', 'Ответ: «Нейросеть исказит нашу одежду»', 'Нейросеть исказит нашу одежду', 'Ответная тактика: - признать риск; - объяснить, что точность товара является обязательным условием; - заранее определить неизменяемые детали; - использовать контрольные исходники; - согласовать тестовый кадр; - не использовать результат, если модель, ткань, цвет, крой или декор переданы неверно.', 'Ответная тактика: - признать риск; - объяснить, что точность товара является обязательным условием; - заранее определить неизменяемые детали; - использовать контрольные исходники; - согласовать тестовый кадр; - не использовать результат, если модель, ткань, цвет, крой или декор переданы неверно.', NULL, 'Уточнить факты и согласовать безопасный следующий шаг.', 'any', 'firm', 'recommended', 'elevated', 'notion', 'https://app.notion.com/p/3aba54abb3e281d18091f4bfa67ef8e3?pvs=204', 'Бренды одежды и текстиля', 'approved', 1, 'priority-a-clothing-objection-1'),
  ('ki-a-clothing-ob2', 'objection_response', 'creator', 'objections', 'Ответ: «Покупатель поймёт, что это нейросеть»', 'Покупатель поймёт, что это нейросеть', 'Сместить разговор с сокрытия технологии на качество и честность подачи. Необходимо объяснить: задача — не обмануть покупателя, а создать выразительную рекламную среду вокруг реального продукта. Сам товар и его ключевые характеристики должны соответствовать действительности.', 'Сместить разговор с сокрытия технологии на качество и честность подачи. Необходимо объяснить: задача — не обмануть покупателя, а создать выразительную рекламную среду вокруг реального продукта. Сам товар и его ключевые характеристики должны соответствовать действительности.', NULL, 'Зафиксировать границы решения до начала производства.', 'any', 'firm', 'recommended', 'elevated', 'notion', 'https://app.notion.com/p/3aba54abb3e281d18091f4bfa67ef8e3?pvs=204', 'Бренды одежды и текстиля', 'approved', 1, 'priority-a-clothing-objection-2'),
