  ('ki-a-jewelry-q2', 'question_to_client', 'creator', 'context', 'Есть ли конкретный запуск, сезон или проблема', 'Есть ли конкретный запуск, сезон или проблема?', NULL, NULL, NULL, NULL, 'any', 'business', 'recommended', 'normal', 'notion', 'https://app.notion.com/p/3aba54abb3e281abbea5fe4f6a2df4a3?pvs=204', 'Украшения и женские аксессуары', 'approved', 1, 'priority-a-jewelry-question-2'),
  ('ki-a-jewelry-ob1', 'objection_response', 'creator', 'objections', 'Ответ: «Нейросеть изменит мой товар»', 'Нейросеть изменит мой товар', 'Ответная тактика: - признать обоснованность страха; - объяснить, что форма, материал, цвет, фурнитура, камни и пропорции фиксируются как критически важные признаки; - предложить контрольные сравнения с исходником; - определить допустимый и недопустимый уровень изменений до начала работы; - для точных карточек использовать реальные предметные исходники и ограничивать генеративные изменения окружением.', 'Ответная тактика: - признать обоснованность страха; - объяснить, что форма, материал, цвет, фурнитура, камни и пропорции фиксируются как критически важные признаки; - предложить контрольные сравнения с исходником; - определить допустимый и недопустимый уровень изменений до начала работы; - для точных карточек использовать реальные предметные исходники и ограничивать генеративные изменения окружением.', NULL, 'Уточнить факты и согласовать безопасный следующий шаг.', 'any', 'firm', 'recommended', 'elevated', 'notion', 'https://app.notion.com/p/3aba54abb3e281abbea5fe4f6a2df4a3?pvs=204', 'Украшения и женские аксессуары', 'approved', 1, 'priority-a-jewelry-objection-1'),
