INSERT OR IGNORE INTO knowledge_items (
  id, item_type, speaker, category, title, prompt_text, short_text, full_text, clarification_text, next_action_text, channel, tone, required_level, risk_level, source_kind, source_url, source_reference, status, version, normalized_key, reviewed_at, created_at, updated_at
)
SELECT
  id, item_type, speaker, category, title, prompt_text, short_text, full_text, clarification_text, next_action_text, channel, tone, required_level, risk_level, source_kind, source_url, source_reference, status, version, normalized_key, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM seed;

WITH niche_map (source_slug, niche_id) AS (
  VALUES
  ('clothing', 'niche-clothing'),
  ('jewelry', 'niche-jewelry'),
  ('home', 'niche-home'),
  ('marketplaces', 'niche-marketplaces'),
  ('packaged_food', 'niche-food-packaged'),
  ('islamic_goods', 'niche-islamic'),
  ('books', 'niche-books'),
  ('bakery', 'niche-bakery'),
  ('hospitality', 'niche-horeca'),
  ('manufacturing', 'niche-manufacturing'),
  ('flowers', 'niche-flowers')
)
INSERT OR IGNORE INTO knowledge_item_niches (knowledge_item_id, niche_id, relevance)
SELECT ki.id, nm.niche_id, 'primary'
FROM knowledge_items ki
JOIN niche_map nm ON ki.id LIKE 'ki-a-' || nm.source_slug || '-%';

INSERT OR IGNORE INTO knowledge_item_stages (knowledge_item_id, stage_id)
SELECT id, 'stage-full-diagnostic'
FROM knowledge_items
WHERE id LIKE 'ki-a-%-q%';

INSERT OR IGNORE INTO knowledge_item_stages (knowledge_item_id, stage_id)
SELECT id, 'stage-objections'
FROM knowledge_items
WHERE id LIKE 'ki-a-%-ob%';

INSERT OR IGNORE INTO knowledge_item_stages (knowledge_item_id, stage_id)
SELECT id, 'stage-audit'
FROM knowledge_items
WHERE id LIKE 'ki-a-%-eth%';
